using UnityEngine;

namespace PuzzleKingdoms.Data
{
    /// <summary>The kinds of screen that have their own music (PB-33). A theme without a clip falls back to the default loop.</summary>
    public enum MusicTheme
    {
        Map = 0,
        Puzzle = 1,
        Battle = 2,
        Results = 3,
    }

    /// <summary>
    /// Every sound the game plays and how loud (PB-8). The placeholder clips are
    /// generated by <c>Puzzle Kingdoms → Generate Placeholder Sounds</c>; to use
    /// real sounds, drop the files into the project and drag them into these fields.
    /// </summary>
    [CreateAssetMenu(menuName = "Puzzle Kingdoms/Sound Bank", fileName = "SoundBank")]
    public sealed class SoundBank : ScriptableObject
    {
        [Header("Puzzle")]
        [Tooltip("Any match clearing; its pitch rises with each cascade wave.")]
        [SerializeField] private AudioClip match;
        [SerializeField] private AudioClip blastCreated;
        [SerializeField] private AudioClip blastFired;
        [SerializeField] private AudioClip prismCreated;
        [SerializeField] private AudioClip prismFired;
        [SerializeField] private AudioClip stoneCrack;
        [SerializeField] private AudioClip invalidSwap;
        [Tooltip("A recruitment meter filled and gave a unit.")]
        [SerializeField] private AudioClip unitRecruited;
        [SerializeField] private AudioClip rallyCharge;

        [Header("Battle (PB-12)")]
        [SerializeField] private AudioClip swordHit;
        [SerializeField] private AudioClip bowShot;
        [SerializeField] private AudioClip magicCast;
        [SerializeField] private AudioClip unitDied;
        [Tooltip("Rally starts in the battle.")]
        [SerializeField] private AudioClip rallyStart;

        [Header("Music")]
        [Tooltip("The default loop: plays under every screen that has no music of its own below.")]
        [SerializeField] private AudioClip music;
        [Tooltip("Map, Kingdom, Commanders, Quests, Shop, Daily and Expedition screens.")]
        [SerializeField] private AudioClip mapMusic;
        [Tooltip("The puzzle and the War Camp.")]
        [SerializeField] private AudioClip puzzleMusic;
        [SerializeField] private AudioClip battleMusic;
        [Tooltip("Victory and defeat screens: a short piece, it may not loop.")]
        [SerializeField] private AudioClip resultsMusic;
        [Tooltip("Seconds to cross-fade from one music to the next.")]
        [SerializeField, Range(0.2f, 4f)] private float musicFadeSeconds = 1.2f;

        [Header("Mix")]
        [Tooltip("Pitch added per cascade wave: 1.0, 1.08, 1.16, ...")]
        [SerializeField, Range(0f, 0.3f)] private float cascadePitchStep = 0.08f;
        [SerializeField, Range(1f, 2f)] private float maxCascadePitch = 1.4f;
        [SerializeField, Range(0f, 1f)] private float effectsVolume = 0.8f;
        [SerializeField, Range(0f, 1f)] private float musicVolume = 0.25f;

        public AudioClip Match => match;
        public AudioClip BlastCreated => blastCreated;
        public AudioClip BlastFired => blastFired;
        public AudioClip PrismCreated => prismCreated;
        public AudioClip PrismFired => prismFired;
        public AudioClip StoneCrack => stoneCrack;
        public AudioClip InvalidSwap => invalidSwap;
        public AudioClip UnitRecruited => unitRecruited;
        public AudioClip RallyCharge => rallyCharge;
        public AudioClip SwordHit => swordHit;
        public AudioClip BowShot => bowShot;
        public AudioClip MagicCast => magicCast;
        public AudioClip UnitDied => unitDied;
        public AudioClip RallyStart => rallyStart;
        public AudioClip Music => music;
        public float MusicFadeSeconds => musicFadeSeconds;

        /// <summary>The music of a theme; the default loop when the theme has none.</summary>
        public AudioClip ClipFor(MusicTheme theme)
        {
            AudioClip clip = theme == MusicTheme.Map ? mapMusic
                : theme == MusicTheme.Puzzle ? puzzleMusic
                : theme == MusicTheme.Battle ? battleMusic
                : resultsMusic;
            return clip != null ? clip : music;
        }
        public float EffectsVolume => effectsVolume;
        public float MusicVolume => musicVolume;

        /// <summary>Pitch of the match sound for cascade wave <paramref name="stepIndex"/> (0 = the player's own match).</summary>
        public float CascadePitch(int stepIndex) =>
            Mathf.Min(1f + Mathf.Max(0, stepIndex) * cascadePitchStep, maxCascadePitch);
    }
}
